 if(t>=32){note('drums','hat',0,t+.25,.085,.1*e,-.35);if(t>=62)note('drums','hat',0,t+.375,.063,.038*e,.43);}
 if(step===1&&t>=60)note('drums','hat',0,t+.25,.32,.09*e,.35);
