  const fade=1-K.ease(t/1.1)+K.ease((t-215.3)/.7);if(fade>0){ctx.fillStyle=`rgba(0,0,0,${Math.min(1,fade)})`;ctx.fillRect(0,0,1920,1080);}ctx.setTransform(1,0,0,1,0,0);
